    def _eval_subs(self, old, new):
        """
        Override _eval_subs to properly handle substitution in ImageSet.

        This ensures that when an ImageSet is used in contexts like 
        ConditionSet, substitution operations behave correctly and don't
        accidentally substitute the dummy variables.
        """
        # Call the parent class's _eval_subs method
        from sympy.core.basic import Basic
        from sympy.core.function import Lambda

        # Handle the case where we're substituting the lambda expression
        # or the base sets appropriately
        if old == self.lamda:
            # If we're substituting the lambda itself, we need to be careful
            return self.func(new, *self.base_sets)
        elif old in self.lamda.variables:
            # If we're substituting one of the lambda variables,
            # we need to update the lambda expression accordingly
            from sympy.core.symbol import Symbol
            from sympy.core.expr import Expr

            # Create a new lambda with updated variables
            new_lambda = self.lamda.subs(old, new)
            return self.func(new_lambda, *self.base_sets)
        else:
            # For other substitutions, delegate to parent class
            return Basic._eval_subs(self, old, new)

    @property
    def is_iterable(self):
